const $=id=>document.getElementById(id);const fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(Number(n||0));const date=s=>s?new Intl.DateTimeFormat('en-US',{dateStyle:'medium'}).format(new Date(s)):'—';function notice(text,ok=true){$('notice').innerHTML=`<div class="notice ${ok?'ok':'bad'}">${text}</div>`}async function load(){try{const r=await fetch('/api/dashboard');const d=await r.json();if(!r.ok)throw Error(d.error);const s=d.summary||{};$('needed').textContent=fmt(s.hoursNeeded);$('filled').textContent=fmt(s.hoursFilled);$('remaining').textContent=fmt(s.hoursRemaining);$('events').textContent=fmt(s.activeEvents);$('rate').textContent=`${Math.round(s.fillRate||0)}% fill rate`;$('open').textContent=`${s.openSlots||0} open slots`;$('assigned').textContent=`${s.assignedSlots||0} assigned slots`;$('last').textContent=date(s.lastSyncAt);const p=d.programs||[];$('programs').innerHTML=p.length?p.map(x=>`<div class="row"><strong>${esc(x.name)}</strong><span>${fmt(x.needed)}</span><span>${fmt(x.filled)}</span><span>${fmt(x.remaining)}</span><div><div class="bar"><i style="width:${Math.min(100,Math.max(0,x.fillRate||0))}%"></i></div><small>${Math.round(x.fillRate||0)}%</small></div></div>`).join(''):'<div class="empty">No program data yet.</div>';const e=d.events||[];$('eventList').innerHTML=e.length?e.map(x=>`<div class="event"><strong>${esc(x.title)}</strong><small>${date(x.eventDate)} · ${esc(x.location||'Location not set')}</small><div class="nums"><span>${fmt(x.hoursFilled)} filled</span><span>${fmt(x.hoursNeeded)} needed</span><span>${x.openSlots||0} open</span></div><div class="bar"><i style="width:${x.hoursNeeded?Math.min(100,x.hoursFilled/x.hoursNeeded*100):0}%"></i></div></div>`).join(''):'<div class="empty">No active events have been synchronized.</div>'}catch(e){notice(e.message||'Unable to load dashboard',false)}}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}$('sync').onclick=async()=>{const b=$('sync');b.disabled=true;b.textContent='Syncing…';try{const r=await fetch('/api/sync',{method:'POST'});const d=await r.json();if(!r.ok)throw Error(d.error);notice(d.message,true);await load()}catch(e){notice(e.message||'Sync failed',false)}finally{b.disabled=false;b.textContent='Sync SignUpGenius'}};load();